# fx_stop_marker_neutral: 48x48 (1x) looping ground-ring pulse, anchor bottom-centre (0.5,1.0). Original, CC0.
# Neutral on purpose: no gift, coin or treasure sparkle. Colours from styleframe/palette.css.
import os,re,math,json
HERE=os.path.dirname(os.path.abspath(__file__))
T=dict(re.findall(r'--hw-([\w-]+):\s*([^;]+);',open(os.path.join(HERE,"../styleframe/palette.css")).read())); T={k:v.strip() for k,v in T.items()}
INK,TEAL,TD,CANDLE,CREAM=T["ink"],T["teal"],T["teal-dark"],T["candle"],T["cream"]
N,FPS,S=12,12,48; CX,CY=24,38      # ring centre; ground plane ellipse, ry = rx*0.42 (3/4 view)
def ring(rx,**a): return f'<ellipse cx="{CX}" cy="{CY}" rx="{rx:.2f}" ry="{rx*.42:.2f}" '+" ".join(f'{k.replace("_","-")}="{v}"' for k,v in a.items())+'/>'
def frame(t):
    br=.5-.5*math.cos(2*math.pi*t)                  # 0..1..0 breathing, seamless
    g=[f'<defs><radialGradient id="gl"><stop offset="0" stop-color="{CANDLE}" stop-opacity="{.45+.2*br:.3f}"/><stop offset="1" stop-color="{CANDLE}" stop-opacity="0"/></radialGradient></defs>',
       ring(23.5,fill="url(#gl)")]
    for ph in (0,1/3,2/3):                               # two ripples half a cycle apart -> continuous
        p=(t+ph)%1; rx=13+10.5*p; op=math.sin(math.pi*p)**2
        g.append(ring(rx,fill="none",stroke=CREAM,stroke_width="2.5",opacity=f"{op:.3f}"))
    g.append(ring(13,fill=TEAL,stroke=INK,stroke_width=3,opacity="1"))   # base disc, 3px ink
    g.append(ring(6.5+1*br,fill=CANDLE,stroke=TD,stroke_width=1.5))     # inner glow core
    lift=1.5*br                                        # small upright post/ chevron: marks "here", neutral
    g.append(f'<path d="M{CX-7} {CY-25-lift:.2f} L{CX} {CY-17-lift:.2f} L{CX+7} {CY-25-lift:.2f}" fill="none" stroke="{INK}" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/>')
    g.append(f'<path d="M{CX-7} {CY-25-lift:.2f} L{CX} {CY-17-lift:.2f} L{CX+7} {CY-25-lift:.2f}" fill="none" stroke="{CREAM}" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/>')
    return "".join(g)
frames=[frame(i/N) for i in range(N)]
# master SVG: frame 0 static + SMIL-free (engines tween); strip SVG for the 2x render
open(os.path.join(HERE,"fx_stop_marker_neutral.svg"),"w").write(f'<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48"><!-- frame 0 of {N}; full loop generated by make_fx_stop_marker.py --><g id="f0">{frames[0]}</g></svg>')
strip="".join(f'<svg x="{i*96}" y="0" width="96" height="96" viewBox="0 0 48 48">{f.replace("id=\"gl\"",f"id=\"gl{i}\"").replace("url(#gl)",f"url(#gl{i})")}</svg>' for i,f in enumerate(frames))
open(os.path.join(HERE,"fx_stop_marker_neutral_strip@2x.svg"),"w").write(f'<svg xmlns="http://www.w3.org/2000/svg" width="{96*N}" height="96">{strip}</svg>')
json.dump(dict(name="fx_stop_marker_neutral",image="fx_stop_marker_neutral_strip@2x.png",scale=2,frame_size=dict(w=96,h=96),size_1x=dict(w=48,h=48),
  frames=[dict(i=i,x=i*96,y=0,w=96,h=96) for i in range(N)],fps=FPS,loop=True,duration_s=N/FPS,anchor=dict(x=0.5,y=1.0),
  notes="Neutral stop marker: ground ring + ripple + small chevron. Replaces provisional fx_tap_me_pulse. Identical on every night.",license="CC0, original"),
  open(os.path.join(HERE,"fx_stop_marker_neutral.json"),"w"),indent=1)
print("ok",N,FPS)
